{
  "id": "f84ed9e9-6a86-4fac-8e18-7632869d48f1",
  "brandColor": "#709727",
  "isTrigger": false,
  "operationName": "Edit Word With GPT",
  "operationDefinition": {
    "actions": {
      "HTTP_Extract_main_Word_xml": {
        "runAfter": {
          "Get_file_content_7": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "e4bfec89-b721-4a7d-9afc-44469dada284"
        },
        "type": "Http",
        "inputs": {
          "method": "POST",
          "uri": "{{functionBaseUrl}}/api/extract_main_word_xml?code={{functionKey}}",
          "body": {
            "file_content": "@body('Get_file_content_7')"
          },
          "retryPolicy": {
            "type": "none"
          }
        }
      },
      "Condition_If_file_contents_over_LLM_character_limit_then_stop": {
        "actions": {
          "Terminate": {
            "runAfter": {},
            "metadata": {
              "operationMetadataId": "44684773-330f-41f5-8e33-68f26bc8cbfe"
            },
            "type": "Terminate",
            "inputs": {
              "runStatus": "Failed",
              "runError": {
                "message": "Word file contents are too long to edit using this LLM prompt"
              }
            }
          }
        },
        "runAfter": {
          "HTTP_Extract_main_Word_xml": [
            "Succeeded"
          ]
        },
        "expression": {
          "greater": [
            "@length(string(body('HTTP_Extract_main_Word_xml')))",
            60000
          ]
        },
        "metadata": {
          "operationMetadataId": "191b4798-bda9-400d-96d9-039e239674ea"
        },
        "type": "If",
        "description": "GPT4o-mini output token limit is 16,000 or about 60,000 characters"
      },
      "Prompt": {
        "runAfter": {
          "Condition_If_file_contents_over_LLM_character_limit_then_stop": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "8e05d6f6-dd8f-449b-84fc-0ae401528be3"
        },
        "type": "Compose",
        "inputs": "I want to edit a Word (.docx) file. I have un-zipped the file into its component xml parts & extracted the word/document.xml & word/_rels/document.xml files to a JSON object containing their xmls as string values. The JSON is provided below between [Start JSON] & [End JSON]. Please edit the xml string value(s) in the JSON to accomplish my requested changes.\nRequested changes:\n-Translate all existing text & new text in the document to spanish.\n-Change any links directed to www.google.com to direct to www.bing.com. (Changing links requires changing them in the word/document.xml.rels parameter/component.)\n-Redact personally identifying information like names.\n-Add a summary of the document's contents & seeming purpose to the end of the document. Do not duplicate the summary text. And apply yellow highlighting to that summary text. (Highlighting likely requires adding some xml like \"<w:rPr><w:highlight w:val=\"yellow\"/></w:rPr>\" before the text.)\n-Give all text across the entire document a Arial font & a 12 font-size. ()\n\n\n[Start JSON]\n@{body('HTTP_Extract_main_Word_xml')}\n[End JSON]\n\nPlease output a JSON object that maintains key parameter labels from the above JSON for existing parameters like \"word/document.xml\", but now with updated xml strings. And if the xml string for a given parameter/component file doesn't have any updates, then you can exclude that parameter from the output JSON. For parameters/components with updates. do not abbreviate the xml string & do not provide only xml snippets with changes, I need the whole xml strings for the Word file components that have changes."
      },
      "Create_text_with_GPT_using_a_prompt": {
        "runAfter": {
          "Prompt": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "16fbb8f0-3f4d-41fd-80ec-f3ce952459ee"
        },
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_commondataserviceforapps",
            "operationId": "aibuilderpredict_customprompt",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_commondataserviceforapps"
          },
          "parameters": {
            "recordId": "00620cc6-b997-448b-bb27-b39dbf581c64",
            "item/requestv2/Prompt": "@outputs('Prompt')"
          }
        }
      },
      "HTTP_Update_Word": {
        "runAfter": {
          "Create_text_with_GPT_using_a_prompt": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "e4bfec89-b721-4a7d-9afc-44469dada284"
        },
        "type": "Http",
        "inputs": {
          "method": "POST",
          "uri": "{{functionBaseUrl}}/api/update_word_xml?code={{functionKey}}",
          "body": {
            "file_content": "@body('Get_file_content_7')",
            "updated_xml": "@json(outputs('Create_text_with_GPT_using_a_prompt')?['body/responsev2/predictionOutput/text'])"
          },
          "retryPolicy": {
            "type": "none"
          }
        }
      },
      "Create_file_7": {
        "runAfter": {
          "HTTP_Update_Word": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "b1259e05-ad0c-4698-b5cc-4d1c6698ccfb"
        },
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_onedriveforbusiness",
            "operationId": "CreateFile",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_onedriveforbusiness"
          },
          "parameters": {
            "folderPath": "/",
            "name": "@{utcNow()}@{outputs('Get_file_metadata_6')?['body/Name']}",
            "body": "@body('HTTP_Update_Word')"
          }
        },
        "runtimeConfiguration": {
          "contentTransfer": {
            "transferMode": "Chunked"
          }
        }
      },
      "Get_file_metadata_6": {
        "runAfter": {},
        "metadata": {
          "operationMetadataId": "1796706b-e357-4578-b651-8e27cf82b03e"
        },
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_onedriveforbusiness",
            "operationId": "GetFileMetadata",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_onedriveforbusiness"
          },
          "parameters": {
            "id": "Choose File"
          }
        }
      },
      "Get_file_content_7": {
        "runAfter": {
          "Get_file_metadata_6": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "f1c83ed7-93aa-4a09-850b-5906fda19fca"
        },
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_onedriveforbusiness",
            "operationId": "GetFileContent",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_onedriveforbusiness"
          },
          "parameters": {
            "id": "@outputs('Get_file_metadata_6')?['body/Id']",
            "inferContentType": true
          }
        }
      }
    },
    "runAfter": {},
    "metadata": {
      "operationMetadataId": "3f7c7f02-dcb8-47fc-bc46-45c9ea24517e"
    },
    "type": "Scope"
  }
}

{
  "id": "cf239498-b48c-4671-9531-35475a6a3031",
  "brandColor": "#709727",
  "isTrigger": false,
  "operationName": "Compress Image or PDF",
  "operationDefinition": {
    "actions": {
      "Get_file_metadata": {
