            "else": {
              "actions": {
                "Get_file_content": {
                  "runAfter": {},
                  "metadata": {
                    "operationMetadataId": "61bd5fe1-f313-485a-86e7-91eeb7189c02"
                  },
                  "type": "OpenApiConnection",
                  "inputs": {
                    "host": {
