                    },
                    "parameters": {
                      "id": "@outputs('Get_file_metadata')?['body/Id']",
                      "inferContentType": true
                    }
                  }
                }
              }
            },
            "expression": {
              "contains": [
                "@outputs('ExtensionsConvertToPDF')",
                "@last(split(outputs('Get_file_metadata')?['body/Name'], '.'))"
              ]
            },
            "metadata": {
              "operationMetadataId": "72e21d89-1fa0-44f8-8ec0-6b2581a5da4b"
            },
            "type": "If"
          },
          "HTTP_Image_or_PDF_Compression": {
            "runAfter": {
              "FileContent": [
                "Succeeded"
              ]
            },
            "metadata": {
              "operationMetadataId": "27fc25c4-5339-4067-bf7c-c7184fa6472e"
            },
            "type": "Http",
            "inputs": {
              "method": "POST",
              "uri": "{{functionBaseUrl}}/api/compress_image_or_pdf?code={{functionKey}}",
              "body": {
                "compression_rate": 0.6,
                "text_pdf_to_jpg": "YES",
                "file_content": "@outputs('FileContent')"
              },
              "retryPolicy": {
                "type": "none"
              }
            }
          },
          "Create_file": {
            "runAfter": {
              "OutputFileName": [
                "Succeeded"
              ]
            },
            "metadata": {
              "operationMetadataId": "28a1c945-f400-4130-be07-4ddaf21676ae"
            },
            "type": "OpenApiConnection",
            "inputs": {
              "host": {
                "connectionName": "shared_onedriveforbusiness",
                "operationId": "CreateFile",
                "apiId": "/providers/Microsoft.PowerApps/apis/shared_onedriveforbusiness"
              },
              "parameters": {
                "folderPath": "/",
                "name": "@{utcNow()}@{outputs('OutputFileName')}",
                "body": "@body('HTTP_Image_or_PDF_Compression')"
              }
            },
            "runtimeConfiguration": {
              "contentTransfer": {
                "transferMode": "Chunked"
              }
            }
          },
          "Condition_Keep_smaller_file": {
            "actions": {
              "Delete_file": {
                "runAfter": {},
                "metadata": {
                  "operationMetadataId": "80e5ef92-19aa-4f85-851c-294b30bfebd9"
                },
                "type": "OpenApiConnection",
                "inputs": {
                  "host": {
                    "connectionName": "shared_onedriveforbusiness",
                    "operationId": "DeleteFile",
                    "apiId": "/providers/Microsoft.PowerApps/apis/shared_onedriveforbusiness"
                  },
                  "parameters": {
                    "id": "@outputs('Get_file_metadata')?['body/Id']"
                  }
                }
              }
            },
            "runAfter": {
              "Create_file": [
                "Succeeded"
              ]
            },
            "else": {
              "actions": {
                "Delete_file_2": {
                  "runAfter": {},
                  "metadata": {
                    "operationMetadataId": "10d00440-a1f2-49cd-9113-2b33f8ab562e"
                  },
                  "type": "OpenApiConnection",
                  "inputs": {
                    "host": {
                      "connectionName": "shared_onedriveforbusiness",
                      "operationId": "DeleteFile",
                      "apiId": "/providers/Microsoft.PowerApps/apis/shared_onedriveforbusiness"
                    },
                    "parameters": {
                      "id": "@outputs('Create_file')?['body/Id']"
                    }
                  }
                }
              }
            },
            "expression": {
              "less": [
                "@outputs('Create_file')?['body/Size']",
                "@outputs('Get_file_metadata')?['body/Size']"
              ]
            },
            "metadata": {
              "operationMetadataId": "b8aa4d07-dd57-4be3-8917-d63bb724a411"
            },
            "type": "If"
          },
          "FileContent": {
            "runAfter": {
              "Condition_If_convert_extension_convert_to_PDF": [
                "Succeeded"
              ]
            },
            "metadata": {
              "operationMetadataId": "b9ae6a9d-abcf-458f-b197-ed1d6f41c55c"
            },
            "type": "Compose",
            "inputs": "@if(empty(body('Get_file_content')), body('Convert_file'), body('Get_file_content'))"
          },
          "OutputFileName": {
            "runAfter": {
              "HTTP_Image_or_PDF_Compression": [
                "Succeeded"
              ]
            },
            "metadata": {
              "operationMetadataId": "bff076c5-5ee7-49f1-be54-faf670f03473"
            },
            "type": "Compose",
            "inputs": "@if(empty(body('Get_file_content')), concat(outputs('Get_file_metadata')?['body/NameNoExt'], '.pdf'), outputs('Get_file_metadata')?['body/Name'])"
          }
        },
        "runAfter": {
          "AcceptedFileExtensions": [
            "Succeeded"
          ]
        },
        "expression": {
          "contains": [
            "@outputs('AcceptedFileExtensions')",
            "@last(split(outputs('Get_file_metadata')?['body/Name'], '.'))"
          ]
        },
        "metadata": {
          "operationMetadataId": "c5c9e25d-daf2-44b8-a315-7b17358a77a2"
        },
        "type": "If"
      },
      "AcceptedFileExtensions": {
        "runAfter": {
          "Get_file_metadata": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "f8c778a6-fbcf-4108-a008-6c7988f2049b"
        },
        "type": "Compose",
        "inputs": [
          "pdf",
          "docx",
          "doc",
          "ppt",
          "png",
          "jpg",
          "jpeg"
        ]
      }
    },
    "runAfter": {},
    "metadata": {
      "operationMetadataId": "8c21e368-567e-42d6-98f4-43634c7b6533"
    },
    "type": "Scope"
  }
